import sqlite3
from contextlib import closing

def read_status(db, lesson_ids):
    if not lesson_ids:
        return {}
    marks = ', '.join('?' for _ in lesson_ids)
    sql = f'SELECT lesson, done FROM progress WHERE lesson IN ({marks})'
    return dict(db.execute(sql, lesson_ids).fetchall())

with closing(sqlite3.connect(':memory:')) as db:
    db.execute('CREATE TABLE progress (lesson TEXT, done INTEGER)')
    db.executemany('INSERT INTO progress VALUES (?, ?)', [('loops', 1), ('files', 0)])
    assert read_status(db, ['loops', 'files']) == {'loops': 1, 'files': 0}
    assert read_status(db, []) == {}
